      msgid,
      msgctxt: key,
      msgstr: cache[key] ?? msgid,
      references: [surface.source],
      flags: [],
      fuzzy: false,
      obsolete: false,
    }));
    const poPath = join(repoRoot, "l10n", locale, `${surface.id}.po`);
    mkdirSync(dirname(poPath), { recursive: true });
    writeFileSync(poPath, serializePo(entries));
  }
  console.log(`Migrated ${surface.id}: ${Object.keys(sourceCache).length} keys`);
}
"}

