#!/usr/bin/env node
/** One-time migration of all documentation translation-memory caches into PO catalogs. */
import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join, relative } from "node:path";
import { flattenStrings, ENGLISH_UI_STRINGS, NON_ROOT_LOCALES } from "../docs/.vitepress/i18n.ts";
import { GLOSSARY_TERMS } from "../docs/scripts/glossary.ts";
import { listDemoNames, loadDemoI18n } from "../docs/scripts/demo-i18n.ts";
import { collectHomeUnits } from "../docs/scripts/home-i18n.ts";
import { collectUnits, segmentMarkdown } from "../docs/scripts/segment-markdown.ts";
import { walkMarkdown } from "../docs/scripts/check-locale-drift.ts";
import { keyFor } from "../docs/scripts/translation-memory.ts";
import { serializePo, serializePot } from "../tools/i18n-engine/src/po.ts";

const repoRoot = relative(import.meta.dirname, ".");
const docsRoot = join(repoRoot, "docs");
const cacheDir = join(docsRoot, "i18n-cache");
const sourceRoot = join(repoRoot, "l10n", "sources");

interface Unit { context: string; message: string; kind: string; sourceFile: string; }

function docsUnits(surface: string): Unit[] {
  if (surface === "docs.guides") {
    return walkMarkdown(join(docsRoot, "guide")).map((file) => ({
      context: relative(repoRoot, file), message: readFileSync(file, "utf8"), kind: "markdown", sourceFile: relative(repoRoot, file),
    }));
  }
  if (surface === "docs.api") {
    return walkMarkdown(join(docsRoot, "api")).flatMap((file) =>
      collectUnits(segmentMarkdown(readFileSync(file, "utf8")))
        .filter((unit) => unit.kind === "prose")
        .map((unit, index) => ({ context: `${relative(repoRoot, file)}#prose-${String(index)}`, message: unit.text, kind: "prose", sourceFile: relative(repoRoot, file) })),
    );
  }
  if (surface === "docs.home") {
    return collectHomeUnits(readFileSync(join(docsRoot, "index.md"), "utf8"))
      .map((message, index) => ({ context: `docs/index.md#text-${String(index)}`, message, kind: "text", sourceFile: "docs/index.md" }));
  }
  if (surface === "docs.chrome") {
    return flattenStrings(ENGLISH_UI_STRINGS).map(({ path, text }) => ({ context: `docs/.vitepress/i18n.ts#${path}`, message: text, kind: "text", sourceFile: "docs/.vitepress/i18n.ts" }));
  }
  if (surface === "docs.glossary") {
    return GLOSSARY_TERMS.map(({ id, term }) => ({ context: `docs/scripts/glossary.ts#${id}`, message: term, kind: "text", sourceFile: "docs/scripts/glossary.ts" }));
  }
  if (surface === "docs.demos") {
    return listDemoNames(join(docsRoot, "demos")).flatMap((name) => {
      const { strings } = loadDemoI18n(join(docsRoot, "demos", name));
      return Object.entries(strings).filter(([, message]) => message !== "").map(([key, message]) => ({ context: `docs/demos/${name}/i18n.json#${key}`, message, kind: "text", sourceFile: `docs/demos/${name}/i18n.json` }));
    });
  }
  throw new Error(`Unsupported docs surface: ${surface}`);
}

const surfaces = ["docs.guides", "docs.api", "docs.home", "docs.chrome", "docs.glossary", "docs.demos"];
mkdirSync(sourceRoot, { recursive: true });
for (const surface of surfaces) {
  const units = docsUnits(surface);
  const source = Object.fromEntries(units.map((unit) => [unit.context, { message: unit.message, translate: "always" }]));
  writeFileSync(join(sourceRoot, `${surface}.json`), `${JSON.stringify(source, null, 2)}\n`);
  const potUnits = units.map((unit) => ({ msgctxt: unit.context, msgid: unit.message, reference: unit.sourceFile }));
  writeFileSync(join(repoRoot, "l10n", `${surface}.pot`), serializePot(potUnits));
  for (const locale of NON_ROOT_LOCALES) {
    const legacyPath = join(cacheDir, `${locale}.${surface.slice("docs.".length)}.json`);
    const legacy = existsSync(legacyPath) ? (JSON.parse(readFileSync(legacyPath, "utf8")) as { entries?: Record<string, string> }).entries ?? {} : {};
    const entries = units.map((unit) => ({
      msgctxt: unit.context, msgid: unit.message, msgstr: legacy[keyFor(unit.kind, unit.message)] ?? unit.message,
      references: [unit.sourceFile], flags: [], fuzzy: false, obsolete: false,
    }));
    const poPath = join(repoRoot, "l10n", locale, `${surface}.po`);
    mkdirSync(join(repoRoot, "l10n", locale), { recursive: true });
    writeFileSync(poPath, serializePo(entries));
  }
  console.log(`${surface}: ${units.length} units`);
}

