import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
const root='docs/demos';
for (const dir of readdirSync(root,{withFileTypes:true}).filter(e=>e.isDirectory())) {
  const path=join(root,dir.name,'i18n.json');
  let raw; try { raw=JSON.parse(readFileSync(path,'utf8')); } catch { continue; }
  const out={'$schema':'../../../i18n.source.schema.json'};
  for (const [key,entry] of Object.entries(raw)) {
    if (typeof entry==='string') { out[key]={message:entry,translate:'always'}; continue; }
    const policy=entry.verbatim;
    if (!policy) { out[key]={message:entry.string,translate:'always'}; continue; }
    if (typeof policy==='string') { out[key]={message:entry.string,translate:policy==='required'?'never':policy==='allow'?'optional':'always'}; continue; }
    const translate={};
    for (const [kind,locales] of Object.entries(policy)) for (const locale of locales) translate[locale]=kind==='required'?'never':kind==='allow'||kind==='warn'?'optional':'always';
    out[key]={message:entry.string,translate:Object.keys(translate).length?translate:'always'};
  }
  writeFileSync(path,JSON.stringify(out,null,2)+'\n');
}
EOF
