  const seen = new Set<string>();
  for (const entry of parsePo(readFileSync(path, "utf8"))) {
    const key = `${entry.msgctxt ?? ""}\0${entry.msgid}`;
    if (seen.has(key)) errors.push(`${path}: duplicate catalog identity ${JSON.stringify(key)}`);
    seen.add(key);
  }
}

